.darma-loader-darma-b13-paper-clip-chain { --accent: var(--loader-color, #94a3b8); --accent-2: var(--loader-secondary-color, #f43f5e); width: calc(var(--loader-size, 116px) * .5); height: var(--loader-size, 116px); position: relative; display: flex; flex-direction: column; align-items: center; padding-top: 8%; }
.darma-loader-darma-b13-paper-clip-chain::before { content: ''; position: absolute; top: 0; left: 40%; width: 20%; height: 9%; border: calc(var(--loader-size, 116px) * .028) solid var(--loader-color, #94a3b8); border-top: 0; border-radius: 0 0 999px 999px; }
.darma-loader-darma-b13-paper-clip-chain span { width: 52%; height: 30%; border: calc(var(--loader-size, 116px) * .045) solid var(--accent); border-radius: 999px; transform-origin: top center; animation: darma-loader-darma-b13-paper-clip-chain-dangle calc(var(--loader-speed, 1s) * 1.9) ease-in-out infinite; }
.darma-loader-darma-b13-paper-clip-chain span:nth-child(2) { margin-top: -9%; border-color: var(--accent-2); animation-delay: calc(var(--loader-speed, 1s) * .14); }
.darma-loader-darma-b13-paper-clip-chain span:nth-child(3) { margin-top: -9%; animation-delay: calc(var(--loader-speed, 1s) * .28); }
@keyframes darma-loader-darma-b13-paper-clip-chain-dangle { 0%, 100% { transform: rotate(-12deg); } 50% { transform: rotate(12deg); } }

